CREATE TABLE IF NOT EXISTS character_profiles_314 (
  profile_id VARCHAR(40) PRIMARY KEY,
  character_name VARCHAR(120),
  archetype_class VARCHAR(80),
  stat_weight_pi DECIMAL(6,2),
  armor_weight_pi DECIMAL(6,2),
  weapon_weight_pi DECIMAL(6,2),
  vfx_type VARCHAR(40),
  commands_stack TEXT
);

